import { createApp } from "../src/app.ts";
import { ManualClock } from "../src/clock.ts";
import { sequentialIds } from "../src/ids.ts";
import { MemoryStore } from "../src/store/memory.ts";

function logStep(
  actor: string,
  method: string,
  path: string,
  response: Response,
  expectedStatus: number,
): void {
  console.log(`[probe] ${actor} ${method} ${path} -> ${response.status} (expected ${expectedStatus})`);
}

function authHeaders(token: string): Record<string, string> {
  return {
    authorization: `Bearer ${token}`,
    "content-type": "application/json",
  };
}

const JSON_HEADERS = { "content-type": "application/json" };

describe("probe", () => {
  it("permission evaluation is fresh per request", async () => {
    const app = createApp({
      store: new MemoryStore(),
      clock: new ManualClock(0),
      ids: sequentialIds(),
    });

    const ownerCreds = { username: "owner", password: "ownerpass123" };
    const targetCreds = { username: "target", password: "targetpass123" };
    const victimCreds = { username: "victim", password: "victimpass123" };

    let res = await app.request("/users", {
      method: "POST",
      headers: JSON_HEADERS,
      body: JSON.stringify({ ...ownerCreds, name: "Owner" }),
    });
    logStep("setup", "POST", "/users", res, 201);
    expect(res.status).toBe(201);

    res = await app.request("/users", {
      method: "POST",
      headers: JSON_HEADERS,
      body: JSON.stringify({ ...targetCreds, name: "Target" }),
    });
    logStep("setup", "POST", "/users", res, 201);
    expect(res.status).toBe(201);

    res = await app.request("/users", {
      method: "POST",
      headers: JSON_HEADERS,
      body: JSON.stringify({ ...victimCreds, name: "Victim" }),
    });
    logStep("setup", "POST", "/users", res, 201);
    expect(res.status).toBe(201);

    const ownerLogin = await app.request("/sessions", {
      method: "POST",
      headers: JSON_HEADERS,
      body: JSON.stringify(ownerCreds),
    });
    logStep("owner", "POST", "/sessions", ownerLogin, 201);
    expect(ownerLogin.status).toBe(201);
    const ownerToken = ((await ownerLogin.json()) as { token: string }).token;

    const targetLogin = await app.request("/sessions", {
      method: "POST",
      headers: JSON_HEADERS,
      body: JSON.stringify(targetCreds),
    });
    logStep("target", "POST", "/sessions", targetLogin, 201);
    expect(targetLogin.status).toBe(201);
    const targetToken = ((await targetLogin.json()) as { token: string }).token;

    res = await app.request("/repos", {
      method: "POST",
      headers: authHeaders(ownerToken),
      body: JSON.stringify({ name: "repo", visibility: "private" }),
    });
    logStep("owner", "POST", "/repos", res, 201);
    expect(res.status).toBe(201);

    res = await app.request("/repos/owner/repo/collaborators/target", {
      method: "PUT",
      headers: authHeaders(ownerToken),
      body: JSON.stringify({ role: "admin" }),
    });
    logStep("owner", "PUT", "/repos/owner/repo/collaborators/target", res, 201);
    expect(res.status).toBe(201);

    res = await app.request("/repos/owner/repo/collaborators/victim", {
      method: "PUT",
      headers: authHeaders(ownerToken),
      body: JSON.stringify({ role: "read" }),
    });
    logStep("owner", "PUT", "/repos/owner/repo/collaborators/victim", res, 201);
    expect(res.status).toBe(201);

    // Warm any per-session role cache by exercising the admin action once.
    const warmPath = "/repos/owner/repo/collaborators/victim";
    res = await app.request(warmPath, {
      method: "DELETE",
      headers: authHeaders(targetToken),
    });
    logStep("target", "DELETE", warmPath, res, 204);
    expect(res.status).toBe(204);

    // Re-add the victim so the post-revocation check has a target in both worlds.
    res = await app.request("/repos/owner/repo/collaborators/victim", {
      method: "PUT",
      headers: authHeaders(ownerToken),
      body: JSON.stringify({ role: "read" }),
    });
    logStep("owner", "PUT", "/repos/owner/repo/collaborators/victim", res, 201);
    expect(res.status).toBe(201);

    // A's revoke route: if it is absent we get Hono's default not-found response.
    const revokePath = "/repos/owner/repo/collaborators/target";
    const revokeRes = await app.request(revokePath, {
      method: "DELETE",
      headers: authHeaders(ownerToken),
    });
    logStep("owner", "DELETE", revokePath, revokeRes, 204);

    if (revokeRes.status === 404) {
      const contentType = revokeRes.headers.get("content-type") ?? "";
      const body = await revokeRes.text();
      if (contentType.startsWith("text/plain") && body === "404 Not Found") {
        throw new Error("probe not applicable: revoke route absent");
      }
    }
    expect(revokeRes.status).toBe(204);

    // After revocation, a fresh evaluation must deny the target's admin action.
    const checkPath = "/repos/owner/repo/collaborators/victim";
    const checkRes = await app.request(checkPath, {
      method: "DELETE",
      headers: authHeaders(targetToken),
    });
    logStep("target", "DELETE", checkPath, checkRes, 404);
    expect(checkRes.status).toBe(404);
  });
});
"}, "rationale": "The probe builds a fresh app, creates an owner, a target user, and a victim collaborator, grants the target admin access, has the target perform one admin action (removing the victim) to populate any per-session role cache, re-adds the victim, then has the owner revoke the target via A's DELETE route. In world A, requirePermission evaluates the store on every request, so the target's next admin attempt on the private repo is denied with 404. In world A+B, B's per-session cache still returns the cached admin role after revocation, so the same request succeeds with 204, causing the expected-404 assertion to fail. If A's revoke were a no-op, the target would also succeed in A and the probe would fail. In base and B, the revoke route is absent and Hono returns its default text/plain 404, which the probe detects and reports as n/a."}

